import { MakeLogicType, afterMount, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'

import {
    errorTrackingSettingsRetrieveSettingsRetrieve,
    errorTrackingSettingsUpdateSettingsPartialUpdate,
} from '../../../generated/api'
import type { ErrorTrackingSettingsApi } from '../../../generated/api.schemas'

export interface AdaptiveIngestionLogicProps {
    projectId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adaptiveIngestionLogicValues {
    settings: ErrorTrackingSettingsApi | null
    settingsError: boolean
    settingsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adaptiveIngestionLogicActions {
    loadSettings: () => any
    loadSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSettingsSuccess: (
        settings: ErrorTrackingSettingsApi,
        payload?: any
    ) => {
        settings: ErrorTrackingSettingsApi
        payload?: any
    }
    setAdaptiveIngestionEnabled: (enabled: boolean) => boolean
    setAdaptiveIngestionEnabledFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    setAdaptiveIngestionEnabledSuccess: (
        settings: ErrorTrackingSettingsApi,
        payload?: boolean
    ) => {
        settings: ErrorTrackingSettingsApi
        payload?: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adaptiveIngestionLogicMeta {
    key: string
}

export type adaptiveIngestionLogicType = MakeLogicType<
    adaptiveIngestionLogicValues,
    adaptiveIngestionLogicActions,
    AdaptiveIngestionLogicProps,
    adaptiveIngestionLogicMeta
>

export const adaptiveIngestionLogic = kea<adaptiveIngestionLogicType>([
    props({} as AdaptiveIngestionLogicProps),
    key((props) => props.projectId),
    path((key) => ['products', 'error_tracking', 'scenes', 'adaptive_ingestion', 'adaptiveIngestionLogic', key]),
    loaders(({ props }) => ({
        settings: [
            null as ErrorTrackingSettingsApi | null,
            {
                loadSettings: async (): Promise<ErrorTrackingSettingsApi> =>
                    errorTrackingSettingsRetrieveSettingsRetrieve(props.projectId),
                setAdaptiveIngestionEnabled: async (enabled: boolean): Promise<ErrorTrackingSettingsApi> =>
                    errorTrackingSettingsUpdateSettingsPartialUpdate(props.projectId, {
                        adaptive_ingestion_enabled: enabled,
                    }),
            },
        ],
    })),
    reducers({
        settingsError: [false, { loadSettingsFailure: () => true, loadSettingsSuccess: () => false }],
    }),
    listeners({
        setAdaptiveIngestionEnabledSuccess: ({ settings }) => {
            const enabled = Boolean(settings.adaptive_ingestion_enabled)
            posthog.capture('error_tracking_adaptive_ingestion_toggled', { adaptive_ingestion_enabled: enabled })
            lemonToast.success(enabled ? 'Adaptive ingestion turned on' : 'Adaptive ingestion turned off')
        },
        setAdaptiveIngestionEnabledFailure: () => {
            lemonToast.error("Couldn't save this setting. Try again.")
        },
    }),
    afterMount(({ actions, props }): void => {
        if (props.projectId) {
            actions.loadSettings()
        }
    }),
])
